  "sql": "WITH _base AS (\n  SELECT\n    CAST(EXTRACT(ISODOW FROM orders.order_date) AS INT) AS \"orders.dow\",\n    CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.revenue\"\n  FROM orders AS orders\n  WHERE\n    (\n      orders.order_date >= CAST('2025-01-01' AS DATE)\n      AND orders.order_date < CAST('2026-01-01' AS DATE)\n    )\n  GROUP BY\n    CAST(EXTRACT(ISODOW FROM orders.order_date) AS INT)\n), _cm_orders__amount_sum_partition_by AS (\n  SELECT\n    CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.amount_sum_partition_by\"\n  FROM orders AS orders\n  WHERE\n    (\n      orders.order_date >= CAST('2025-01-01' AS DATE)\n      AND orders.order_date < CAST('2026-01-01' AS DATE)\n    )\n)\nSELECT\n  _base.\"orders.dow\",\n  _base.\"orders.revenue\",\n  _base.\"orders.revenue\" / NULLIF(_cm_orders__amount_sum_partition_by.\"orders.amount_sum_partition_by\", 0) AS \"orders.share\"\nFROM _base\nCROSS JOIN _cm_orders__amount_sum_partition_by\nORDER BY\n  _base.\"orders.dow\" ASC\nLIMIT 101"
